        if (aiResponse.IsFailure)
            return aiResponse.Error;

        // Store conversation
        var conversation = new Conversation(
            ConversationId.New(),
            request.UserId,
            request.Message,
            aiResponse.Value);

        await _chatRepository.SaveAsync(conversation, ct);

        return new ChatResponse(aiResponse.Value, conversation.Id.Value);
